#!/usr/bin/env Rscript

suppressPackageStartupMessages(library(Rcpp));options(stringsAsFactors=FALSE,warn=1)
args<-commandArgs(trailingOnly=TRUE);arg_value<-function(name,default){z<-grep(paste0("^--",name,"="),args,value=TRUE);if(length(z))sub(paste0("^--",name,"="),"",z[[1]])else default}
mode<-arg_value("mode","quick");if(!mode%in%c("quick","full"))stop("--mode must be quick or full");n<-as.integer(arg_value("n","200"));p<-as.integer(arg_value("p","200"));blocks<-10L;block_size<-5L;datasets<-as.integer(arg_value("datasets",if(mode=="quick")"1" else "10"));chains<-4L;budget<-as.numeric(arg_value("budget",if(mode=="quick")".5" else "5"));burn<-as.integer(arg_value("burn",if(mode=="quick")"100" else "500"));rho<-as.numeric(arg_value("rho",".95"));out_dir<-arg_value("output","Simulations/Correlated_Score_Sensitivity/Results/New_Run");marginal_audit<-arg_value("marginal-audit",file.path("Simulations/Validation/Results/New_Run/Marginal_Scores/summary.csv"));production_audit<-arg_value("production-audit",file.path("Simulations/Validation/Results/New_Run/Gaussian_Updates/summary.csv"));for(f in c(marginal_audit,production_audit))if(!file.exists(f)||!isTRUE(read.csv(f)$passed[[1]]))stop("Required proposal audit has not passed: ",f);source(file.path("Simulations/Validation/gaussian_support.R"));revision_initialize(out_dir,require_audit=TRUE);for(audit_path in c(marginal_audit,production_audit))revision_require_audit(dirname(audit_path))
Rcpp::sourceCpp(file.path("Simulations/gaussian_kernels.cpp"),cacheDir=file.path("Simulations/.rcpp_cache"),rebuild=FALSE)
ess_basic<-function(x){if(length(x)<20||!is.finite(var(x))||var(x)==0)return(NA_real_);z<-as.numeric(acf(x,lag.max=min(length(x)-1,1000),plot=FALSE)$acf)[-1];m<-length(z)-length(z)%%2;if(m<2)return(length(x));q<-z[seq(1,m,2)]+z[seq(2,m,2)];k<-match(TRUE,q<=0,nomatch=length(q)+1);keep<-if(k==1)numeric()else q[seq_len(k-1)];min(length(x),length(x)/(1+2*sum(keep)))}
rank_split_rhat<-function(chains){L<-min(vapply(chains,length,integer(1)));h<-floor(L/2);if(h<20)return(NA_real_);s<-unlist(lapply(chains,function(x)list(x[seq_len(h)],x[(L-h+1):L])),recursive=FALSE);z<-qnorm((rank(unlist(s),ties.method="average")-.5)/(length(s)*h));M<-matrix(z,nrow=h);W<-mean(apply(M,2,var));B<-h*var(colMeans(M));if(W==0)return(1);sqrt(((h-1)/h*W+B/h)/W)}
simulate_data<-function(seed){set.seed(seed);X<-matrix(rnorm(n*p),n,p);for(b in seq_len(blocks)){idx<-((b-1)*block_size+1):(b*block_size);latent<-rnorm(n);X[,idx]<-sqrt(rho)*latent+sqrt(1-rho)*matrix(rnorm(n*block_size),n)};X<-unclass(scale(X));active<-1+(0:(blocks-1))*block_size;beta<-numeric(p);beta[active]<-rep(c(.8,-.8),length.out=blocks);list(X=X,y=as.numeric(.4+X%*%beta+rnorm(n)),active=active)}
make_starts<-function(active){null<-integer(p);truth<-null;truth[active]<-1L;surrogate<-null;surrogate[active+1L]<-1L;set.seed(991);random<-null;random[sample.int(p,blocks)]<-1L;list(null,truth,surrogate,random)}
rows<-list();pips<-list();adapt<-list();id<-0L;aid<-0L
for(dataset in seq_len(datasets)){dat<-simulate_data(20275000L+dataset);starts<-make_starts(dat$active);for(score in c("f","bic","marginal")){size_traces<-target_traces<-vector("list",chains);first_id<-id+1L;for(chain in seq_len(chains)){set.seed(20276000L+dataset*100L+match(score,c("f","bic","marginal"))*10L+chain);fit<-run_optimized_similarity_scaling(dat$y,dat$X,score,starts[[chain]],budget,burn,max_iterations=1000000L,lambda_initial=.7,adapt_lambda=TRUE,balance_directions=TRUE,adaptation_metric="diversity",target_effective_neighbors=max(5,.025*p),adaptation_gain=.5,adaptation_decay=.6,adaptation_offset=100,uniform_mixture=.02);es<-ess_basic(fit$model_size);et<-ess_basic(fit$log_target);size_traces[[chain]]<-fit$model_size;target_traces[[chain]]<-fit$log_target;id<-id+1L;rows[[id]]<-data.frame(dataset=dataset,chain=chain,score=score,seconds=fit$total_seconds,iterations=fit$iterations,acceptance=fit$postburn_acceptance_rate,lambda_final=fit$final_lambda,mean_effective_neighbors=fit$mean_proposal_effective_neighbors,mean_entropy=fit$mean_proposal_entropy,mean_max_probability=fit$mean_max_proposal_probability,ess_model_size_per_second=es/fit$total_seconds,ess_log_target_per_second=et/fit$total_seconds,mean_active_pip=mean(fit$pips[dat$active]),mean_surrogate_pip=mean(fit$pips[unlist(lapply(dat$active,function(j)(j+1L):(j+block_size-1L)))]),mean_noise_pip=mean(fit$pips[-unique(unlist(lapply(dat$active,function(j)j:(j+block_size-1L))))]));pips[[id]]<-data.frame(dataset=dataset,chain=chain,score=score,variable=seq_len(p),role=ifelse(seq_len(p)%in%dat$active,"active",ifelse(seq_len(p)%in%unlist(lapply(dat$active,function(j)(j+1L):(j+block_size-1L))),"surrogate","noise")),pip=fit$pips);keep<-unique(round(seq(1,length(fit$lambda_trace),length.out=min(250,length(fit$lambda_trace)))));aid<-aid+1L;adapt[[aid]]<-data.frame(dataset=dataset,chain=chain,score=score,retained_iteration=keep,lambda=fit$lambda_trace[keep]);message(sprintf("dataset=%d/%d score=%s chain=%d/%d",dataset,datasets,score,chain,chains))};rsize<-rank_split_rhat(size_traces);rtarget<-rank_split_rhat(target_traces);for(k in first_id:id){rows[[k]]$rhat_model_size<-rsize;rows[[k]]$rhat_log_target<-rtarget}}}
raw<-do.call(rbind,rows);pip<-do.call(rbind,pips);trajectories<-do.call(rbind,adapt);ranges<-aggregate(pip~dataset+score+variable+role,pip,function(x)max(x)-min(x));agreement<-aggregate(pip~score,ranges,mean);names(agreement)[2]<-"mean_between_chain_pip_range";num<-setdiff(names(raw)[vapply(raw,is.numeric,logical(1))],c("dataset","chain"));summary<-merge(aggregate(raw[num],raw["score"],mean,na.rm=TRUE),agreement,by="score",sort=FALSE)
write.csv(raw,file.path(out_dir,"chain_metrics.csv"),row.names=FALSE);write.csv(summary,file.path(out_dir,"method_summary.csv"),row.names=FALSE);write.csv(pip,file.path(out_dir,"pip_estimates.csv"),row.names=FALSE);write.csv(trajectories,file.path(out_dir,"adaptive_trajectories_thinned.csv"),row.names=FALSE);writeLines(c(paste("mode:",mode),paste("n:",n),paste("p:",p),paste("datasets:",datasets),paste("chains:",chains),paste("budget_seconds:",budget),paste("rho:",rho),"kernels: optimized online-adaptive F, BIC, and marginal screening; flip-only","adaptation: balanced directions, 2% mixture, diminishing diversity adaptation throughout sampling"),file.path(out_dir,"manifest.txt"));writeLines(capture.output(sessionInfo()),file.path(out_dir,"sessionInfo.txt"));saveRDS(list(raw=raw,summary=summary,pip=pip,trajectories=trajectories),file.path(out_dir,"chain_results.rds"),compress="xz");print(summary,row.names=FALSE)
